import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { TinyUrlService } from '../../services/tiny-url.service';
import { TinyUrl } from '../../models/tiny-url.model';

@Component({
  selector: 'app-home',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './home.component.html',
  styleUrls: ['./home.component.css']
})
export class HomeComponent implements OnInit {
  // Form state
  inputUrl: string = '';
  isPrivate: boolean = false;
  isLoading: boolean = false;
  errorMsg: string = '';
  successMsg: string = '';

  // URL list state
  urls: TinyUrl[] = [];
  filteredUrls: TinyUrl[] = [];
  searchQuery: string = '';
  copiedCode: string = '';

  constructor(private tinyUrlService: TinyUrlService) {}

  ngOnInit(): void {
    this.loadPublicUrls();
  }

  // ── Load all public URLs ──────────────────────────────────────────────
  loadPublicUrls(): void {
    this.tinyUrlService.getPublicUrls().subscribe({
      next: (data) => {
        this.urls = data;
        this.applySearch();
      },
      error: (err) => {
        console.error('Error loading URLs', err);
      }
    });
  }

  // ── Generate short URL ────────────────────────────────────────────────
  generateUrl(): void {
    this.errorMsg = '';
    this.successMsg = '';

    if (!this.inputUrl.trim()) {
      this.errorMsg = 'Please enter a URL!';
      return;
    }

    this.isLoading = true;

    this.tinyUrlService.createUrl({
      originalUrl: this.inputUrl.trim(),
      isPrivate: this.isPrivate
    }).subscribe({
      next: (created) => {
        this.isLoading = false;
        this.successMsg = `Short URL created: ${created.shortUrl}`;
        this.inputUrl = '';
        this.isPrivate = false;
        this.loadPublicUrls(); // Refresh list
      },
      error: (err) => {
        this.isLoading = false;
        this.errorMsg = err?.error?.error || 'Failed to create URL. Check the URL format.';
      }
    });
  }

  // ── Delete URL ────────────────────────────────────────────────────────
  deleteUrl(code: string): void {
    if (!confirm(`Delete short URL "${code}"?`)) return;

    this.tinyUrlService.deleteUrl(code).subscribe({
      next: () => {
        this.urls = this.urls.filter(u => u.code !== code);
        this.applySearch();
      },
      error: (err) => console.error('Delete failed', err)
    });
  }

  // ── Copy to clipboard ─────────────────────────────────────────────────
  copyToClipboard(shortUrl: string, code: string): void {
    navigator.clipboard.writeText(shortUrl).then(() => {
      this.copiedCode = code;
      setTimeout(() => this.copiedCode = '', 2000);
    });
  }

  // ── Search / filter ───────────────────────────────────────────────────
  applySearch(): void {
    const q = this.searchQuery.toLowerCase().trim();
    this.filteredUrls = q
      ? this.urls.filter(u =>
          u.code.toLowerCase().includes(q) ||
          u.originalUrl.toLowerCase().includes(q) ||
          u.shortUrl.toLowerCase().includes(q)
        )
      : [...this.urls];
  }

  onSearchChange(): void {
    this.applySearch();
  }

  // ── Open short URL in new tab ─────────────────────────────────────────
  openUrl(shortUrl: string): void {
    window.open(shortUrl, '_blank');
  }
}
<!-- home.component.html -->
<div class="page-wrapper">

  <!-- ── Header ── -->
  <header class="header">
    <h1 class="logo">🔗 Tiny<span>URL</span></h1>
    <p class="tagline">Shorten. Share. Track.</p>
  </header>

  <!-- ── URL Generator Card ── -->
  <section class="card generator-card">
    <h2>Shorten a URL</h2>

    <div class="input-row">
      <input
        type="url"
        [(ngModel)]="inputUrl"
        placeholder="https://your-long-url.com/..."
        class="url-input"
        (keyup.enter)="generateUrl()"
      />
      <label class="private-toggle">
        <input type="checkbox" [(ngModel)]="isPrivate" />
        <span>Private</span>
      </label>
    </div>

    <button
      class="btn btn-primary"
      (click)="generateUrl()"
      [disabled]="isLoading"
    >
      {{ isLoading ? 'Generating...' : '⚡ Generate' }}
    </button>

    <!-- Success / Error messages -->
    <div *ngIf="successMsg" class="alert alert-success">✅ {{ successMsg }}</div>
    <div *ngIf="errorMsg" class="alert alert-error">❌ {{ errorMsg }}</div>
  </section>

  <!-- ── Public URLs Section ── -->
  <section class="card list-card">
    <div class="list-header">
      <h2>Public URLs</h2>
      <input
        type="text"
        [(ngModel)]="searchQuery"
        (ngModelChange)="onSearchChange()"
        placeholder="Search URLs..."
        class="search-input"
      />
    </div>

    <!-- Empty state -->
    <div *ngIf="filteredUrls.length === 0" class="empty-state">
      <p>No public URLs found.</p>
    </div>

    <!-- URL List -->
    <div class="url-list">
      <div *ngFor="let url of filteredUrls" class="url-item">
        <div class="url-info">
          <a [href]="url.shortUrl" target="_blank" class="short-url">
            {{ url.shortUrl }}
          </a>
          <span class="original-url" [title]="url.originalUrl">
            → {{ url.originalUrl | slice:0:60 }}{{ url.originalUrl.length > 60 ? '...' : '' }}
          </span>
        </div>

        <div class="url-meta">
          <span class="clicks-badge">
            👆 {{ url.clicks }} click{{ url.clicks !== 1 ? 's' : '' }}
          </span>
        </div>

        <div class="url-actions">
          <button
            class="btn btn-sm btn-copy"
            (click)="copyToClipboard(url.shortUrl, url.code)"
          >
            {{ copiedCode === url.code ? '✅ Copied!' : '📋 Copy' }}
          </button>
          <button
            class="btn btn-sm btn-delete"
            (click)="deleteUrl(url.code)"
          >
            🗑️ Delete
          </button>
        </div>
      </div>
    </div>
  </section>

</div>
